const firstName = pm.variables.replaceIn("{{$randomFirstName}}");
const lastName = pm.variables.replaceIn("{{$randomLastName}}");
const email = pm.variables.replaceIn("{{$randomEmail}}");

const fullName = `${firstName} ${lastName}`;

pm.environment.set("fullname", fullName);
pm.environment.set("mail", email);

const RESPONSE = pm.response;

pm.test("Statuscode ist 201 bei erfolgreicher Registrierung", () => {
    RESPONSE.to.have.status(201);
});

pm.test("Resgistrierung erfolgreich: Token und email validiert", () => {
    const responseData = pm.response.json();

    // Prüfen, ob der Status created ist 201
    pm.expect(pm.response.code).to.eql(201);

    // Prüfen, ob das Token im response existiert und ein string ist
    pm.expect(responseData.token).to.be.exist;
    pm.expect(responseData.token).to.be.a('string');

    // Prüfen, ob die mail im response mitgesendet wurde
    pm.expect(responseData.email).to.be.exist;
    pm.expect(responseData.email).to.be.a('string');
    pm.expect(responseData.email).to.eql(pm.environment.get("mail")); // Vergleicht die email aus dem response mit der email aus dem environment

});

const RESPONSE = pm.response;

pm.test("Statuscode ist 200 bei erfolgreichem login", () => {
    RESPONSE.to.have.status(200);
})

pm.test("Token ist übergeben worden bei erfolgreichem login", () => {
    try{
        const RESPONSEJSON = RESPONSE.json();
        pm.expect(RESPONSEJSON).to.have.property("token");
        // Wenn Prüfungen erfolgreich, dann token in Env sichern
        pm.environment.set("user_token", RESPONSEJSON.token); // Speichert den token in der Umgebungsvariable user_token

        console.log("Token erfolgreich automatisert gespeichert: " + pm.environment.get("user_token"));
    } catch (error){
        pm.expect.fail("Response ist kein valides JSON " + error);
    }
})

